styles:
.b-hero {
    container-type: inline-size;
    background: #0f172a;
    color: #fff;
}

.b-hero__inner {
    max-width: 64rem;
    margin: 0 auto;
    padding: 4rem 1.25rem;
}

.b-hero__title {
    font-size: 2.25rem;
    line-height: 1.1;
    margin: 0 0 1rem;
}

.b-hero__subtitle {
    font-size: 1.125rem;
    color: #cbd5e1;
    max-width: 36rem;
    margin: 0 0 1.5rem;
}

.b-hero__button {
    display: inline-block;
    padding: 0.75rem 1.25rem;
    border-radius: 0.5rem;
    background: #3b82f6;
    color: #fff;
    text-decoration: none;
    font-weight: 600;
}

@container (min-width: 48rem) {
    .b-hero__inner {
        padding: 6rem 1.25rem;
    }

    .b-hero__title {
        font-size: 3.5rem;
    }
}
